import { CRAFT_GUIDE, LANGUAGE_GUIDE, MOTION_GUIDE, PRIMITIVES_GUIDE } from "./guide"
import { describeComponent } from "./prompt"
import { UNSUPPORTED } from "./recipes"
import { UI_SDK_CATALOG, UI_SDK_VERSION } from "./ui-sdk-catalog.generated"

const NOTICE =
  "<!-- Generated by `pnpm generate:skills` from packages/core/src/prompt. Edit the source, not this file. -->"

function page(...sections: string[]): string {
  return `${[NOTICE, ...sections.map((section) => section.trim())].join("\n\n")}\n`
}

/**
 * The reference pages of the agent skills in `skills/`, by path. They are
 * the same text a model gets in its system prompt, so a coding agent that
 * writes markup by hand and a model that writes it live learn one language.
 */
export function skillReferences(): Record<string, string> {
  const components = UI_SDK_CATALOG.map((entry) => describeComponent(entry.slug) ?? "")
  const unsupported = Object.keys(UNSUPPORTED).length
  return {
    "intelligent-ui/references/language.md": page(LANGUAGE_GUIDE, PRIMITIVES_GUIDE, CRAFT_GUIDE),
    "intelligent-ui/references/components.md": page(
      [
        "# UI SDK components",
        "",
        `Every entry point of UI SDK ${UI_SDK_VERSION}, as it is written in markup: ${UI_SDK_CATALOG.length} components,`,
        `${UI_SDK_CATALOG.length - unsupported} of them usable from markup. Parts nest as shown and only work inside their parent.`,
        "For every prop of every part, call `describeComponent(name, { props: true })` from",
        "`@open-intelligent-ui/core/prompt`.",
      ].join("\n"),
      ...components
    ),
    "motion/references/markup.md": page(MOTION_GUIDE),
  }
}
